DROP POLICY "Authenticated users can delete leads" ON public.leads;
CREATE POLICY "Admins can delete leads" ON public.leads FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));
DROP POLICY "Authenticated users can insert landing content" ON public.landing_content;
DROP POLICY "Authenticated users can update landing content" ON public.landing_content;
CREATE POLICY "Admins can insert landing content" ON public.landing_content FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admins can update landing content" ON public.landing_content FOR UPDATE TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
DROP POLICY "Operator landing image delete" ON storage.objects;
DROP POLICY "Operator landing image update" ON storage.objects;
DROP POLICY "Operator landing image upload" ON storage.objects;
DROP POLICY "Operator landing video delete" ON storage.objects;
DROP POLICY "Operator landing video update" ON storage.objects;
DROP POLICY "Operator landing video upload" ON storage.objects;
CREATE POLICY "Admin landing media upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id IN ('landing-images','landing-videos') AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin landing media update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id IN ('landing-images','landing-videos') AND public.has_role(auth.uid(),'admin')) WITH CHECK (bucket_id IN ('landing-images','landing-videos') AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Admin landing media delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id IN ('landing-images','landing-videos') AND public.has_role(auth.uid(),'admin'));
DROP POLICY order_materials_insert ON storage.objects;
DROP POLICY order_materials_orphan_delete ON storage.objects;
DROP POLICY order_materials_read ON storage.objects;
CREATE POLICY order_materials_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id='order-materials' AND name ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.(jpg|jpeg|png|webp|pdf|mp4|webm)$' AND EXISTS (SELECT 1 FROM public.business_orders o LEFT JOIN public.order_workspaces w ON w.order_id=o.id WHERE o.id::text=(storage.foldername(objects.name))[1] AND o.payment_status='paid' AND ((o.user_id=auth.uid() AND COALESCE(w.phase,'materials')='materials') OR public.has_role(auth.uid(),'admin'))));
CREATE POLICY order_materials_orphan_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id='order-materials' AND EXISTS (SELECT 1 FROM public.business_orders o WHERE o.id::text=(storage.foldername(objects.name))[1] AND (o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))) AND NOT EXISTS (SELECT 1 FROM public.order_assets a WHERE a.path=objects.name));
CREATE POLICY order_materials_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id='order-materials' AND EXISTS (SELECT 1 FROM public.business_orders o WHERE o.id::text=(storage.foldername(objects.name))[1] AND (o.user_id=auth.uid() OR public.has_role(auth.uid(),'admin'))));